import { ScatterChart, type ScatterChartZoomDetail } from '@absoluteui/components/scatter-chart';

const host = document.createElement('div');
document.body.append(host);
const chart = ScatterChart.create(host, {
  label: 'Height and weight',
  series: [
    { id: 'a', label: 'Group A', points: [{ x: 160, y: 55 }, { x: 175, y: 72 }, { x: 182, y: 80 }] },
    { id: 'b', label: 'Group B', points: [{ x: 150, y: 48 }, { x: 170, y: 65 }] },
  ],
  xAxis: { label: 'Height (cm)' },
  yAxis: { label: 'Weight (kg)' },
  crosshair: true,
  zoom: 'xy',
});
host.addEventListener('aui-zoom', (event) => {
  const { x, y } = (event as CustomEvent<ScatterChartZoomDetail>).detail;
  host.dataset.zoomed = String(x !== null || y !== null);
});
chart.update({ zoomRange: { from: 155, to: 180 } });

import { ScatterChart } from '@absoluteui/components/scatter-chart';

const host = document.querySelector<HTMLElement>('#markets');
if (host) {
  ScatterChart.create(host, {
    label: 'Markets',
    series: [{
      id: 'm',
      label: 'Markets',
      color: 4,
      points: [
        { x: 2.1, y: 18, size: 120, label: 'North' },
        { x: 3.4, y: 11, size: 60, label: 'South' },
        { x: 1.2, y: 25, size: 300, label: 'West' },
      ],
    }],
    xAxis: { label: 'Growth (%)', includeZero: true },
    yAxis: { label: 'Margin (%)' },
    sizeLabel: 'Revenue (M)',
    sizeRange: [6, 30],
    dataTable: 'visible',
  });
}
